/// Routes whose handler still answers an untyped `serde_json::Value` or an opaque
/// `Response`, so the schema has no fields to sample. Each is a Phase 1 item of the schema
/// remediation plan; when its handler gains a typed reply this test refuses the entry so the
/// row above starts to count.
const UNTYPED_TODAY: &[&str] = &[
    "POST /api/lineage/confirm",
    "POST /api/lineage/reject",
    "POST /api/datasets/{name}/query",
];

const UNTYPED_RESPONSES: &[&str] = &["serde_json::Value", "opaque", "no body", "unknown"];

struct Schemas {
    routes: Vec<Value>,
    types: Map<String, Value>,
}

fn schemas() -> Schemas {
    let doc: Value = serde_json::from_str(SCHEMAS).expect("schemas.json parses");
    Schemas {
        routes: doc["routes"].as_array().expect("routes").clone(),
        types: doc["types"].as_object().expect("types").clone(),
    }
}

impl Schemas {
    fn route(&self, key: &str) -> Option<&Value> {
        let (method, path) = key.split_once(' ').expect("`METHOD /path`");
        self.routes
            .iter()
            .find(|r| r["method"] == method && r["path"] == path)
    }
}

/// `a::b::Name<X, Y>` → (`Name`, `["X", "Y"]`), module path dropped.
fn split_type(ty: &str) -> (String, Vec<String>) {
    let ty = ty.trim();
    let (head, args) = match ty.find('<') {
        Some(i) if ty.ends_with('>') => (&ty[..i], split_top_level(&ty[i + 1..ty.len() - 1])),
        _ => (ty, Vec::new()),
    };
    let name = head.rsplit("::").next().unwrap_or(head).to_string();
    (
        name,
        args.into_iter().map(|s| s.trim().to_string()).collect(),
    )
}

fn split_top_level(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut depth = 0i32;
    let mut start = 0;
    for (i, c) in s.char_indices() {
        match c {
            '<' | '(' | '[' | '{' => depth += 1,
            '>' | ')' | ']' | '}' => depth -= 1,
            ',' if depth == 0 => {
                out.push(s[start..i].to_string());
                start = i + 1;
            }
            _ => {}
        }
    }
    let last = s[start..].trim();
    if !last.is_empty() {
        out.push(last.to_string());
    }
    out
}

const FIXED_UUID: &str = "00000000-0000-4000-8000-000000000000";
const FIXED_TIME: &str = "2026-01-01T00:00:00Z";

/// A JSON value satisfying `ty` as the schema states it, as a server serialises it: a
/// `#[serde(default)]` field is always written, an `Option` without `skip_serializing_if`
/// is written as `null`, and only a `skip_serializing_if` field is absent.
fn sample(ty: &str, types: &Map<String, Value>, depth: usize) -> Value {
    assert!(depth < 16, "sample of {ty} recurses without end");
    let trimmed = ty.trim();
    if let Some(inner) = trimmed.strip_prefix('(').and_then(|s| s.strip_suffix(')')) {
        return Value::Array(
            split_top_level(inner)
                .iter()
                .map(|t| sample(t, types, depth + 1))
                .collect(),
        );
    }
    if let Some(inner) = trimmed.strip_prefix('&') {
        return sample(inner.trim_start_matches("'static").trim(), types, depth + 1);
    }
    let (name, args) = split_type(trimmed);
    match name.as_str() {
        "String" | "str" | "PathBuf" | "Cow" => json!("x"),
        "bool" => json!(false),
        "u8" | "u16" | "u32" | "u64" | "usize" | "i8" | "i16" | "i32" | "i64" | "isize" | "f32"
        | "f64" => json!(0),
        "DateTime" | "NaiveDateTime" | "NaiveDate" => json!(FIXED_TIME),
        "Uuid" => json!(FIXED_UUID),
        "Vec" | "VecDeque" | "HashSet" | "BTreeSet" => {
            json!([sample(&args[0], types, depth + 1)])
        }
        "HashMap" | "BTreeMap" | "Map" => json!({}),
        "Value" => json!({}),
        "Option" => Value::Null,
        "Box" | "Arc" | "Rc" => sample(&args[0], types, depth + 1),
        _ => match types.get(&name) {
            Some(def) => sample_def(def, types, depth + 1),
            None => panic!("schemas.json has no type `{name}` (from `{ty}`)"),
        },
    }
}

fn sample_def(def: &Value, types: &Map<String, Value>, depth: usize) -> Value {
    match def["kind"].as_str().expect("kind") {
        "struct" => sample_fields(def["fields"].as_array().expect("fields"), types, depth),
        "newtype" => sample(def["inner"].as_str().expect("inner"), types, depth),
        "enum" => sample_enum(def, types, depth),
        other => panic!("unknown kind {other}"),
    }
}

fn sample_fields(fields: &[Value], types: &Map<String, Value>, depth: usize) -> Value {
    let mut out = Map::new();
    for f in fields {
        let ty = f["type"].as_str().expect("type");
        let notes = f["notes"].as_array().cloned().unwrap_or_default();
        if notes.iter().any(|n| n == "omitted when empty") {
            continue;
        }
        let flattened = notes.iter().any(|n| n == "flattened into the parent");
        let positional = notes.iter().any(|n| n == "positional");
        let value = sample(ty, types, depth);
        if flattened {
            if let Value::Object(inner) = value {
                out.extend(inner);
            }
            continue;
        }
        if positional {
            return Value::Array(
                fields
                    .iter()
                    .map(|f| sample(f["type"].as_str().expect("type"), types, depth))
                    .collect(),
            );
        }
        out.insert(f["name"].as_str().expect("name").to_string(), value);
    }
    Value::Object(out)
}

/// The first variant in wire form. `payload` is either `{ a: T, b: U }` for a struct variant
/// or a type for a tuple variant.
fn sample_enum(def: &Value, types: &Map<String, Value>, depth: usize) -> Value {
    let representation = def["representation"].as_str().unwrap_or_default();
    let variants = def["variants"].as_array().expect("variants");
    let Some(first) = variants.first() else {
        return Value::Null;
    };
    let name = first["name"].as_str().expect("variant name");
    let payload = first["payload"]
        .as_str()
        .map(|p| sample_payload(p, types, depth));
    if representation.starts_with("internally") {
        let tag = representation
            .split('"')
            .nth(1)
            .unwrap_or("type")
            .to_string();
        let mut obj = match payload {
            Some(Value::Object(fields)) => fields,
            _ => Map::new(),
        };
        obj.insert(tag, json!(name));
        return Value::Object(obj);
    }
    match payload {
        None => json!(name),
        Some(value) => json!({ name: value }),
    }
}

fn sample_payload(payload: &str, types: &Map<String, Value>, depth: usize) -> Value {
    let trimmed = payload.trim();
    match trimmed.strip_prefix('{').and_then(|s| s.strip_suffix('}')) {
        Some(inner) => {
            let mut out = Map::new();
            for field in split_top_level(inner) {
                let (name, ty) = field.split_once(':').expect("`name: Type`");
                let ty = ty.trim();
                let (head, _) = split_type(ty);
                if head == "Option" {
                    continue;
                }
                out.insert(name.trim().to_string(), sample(ty, types, depth));
            }
            Value::Object(out)
        }
        None => sample(trimmed, types, depth),
    }
}

#[test]
fn every_mcp_route_exists_in_the_schema() {
    let schemas = schemas();
    let missing: Vec<&str> = CHECKS
        .iter()
        .map(|(route, _, _)| *route)
        .chain(UNTYPED_TODAY.iter().copied())
        .filter(|route| schemas.route(route).is_none())
        .collect();
    assert!(
        missing.is_empty(),
        "routes the MCP server calls that router.rs no longer registers: {missing:?}"
    );
}

#[test]
fn untyped_today_lists_only_routes_still_untyped() {
    let schemas = schemas();
    for route in UNTYPED_TODAY {
        let found = schemas
            .route(route)
            .unwrap_or_else(|| panic!("{route} is not a route"));
        let response = found["response"].as_str().unwrap_or_default();
        assert!(
            UNTYPED_RESPONSES.contains(&response),
            "{route} now answers `{response}`: drop it from UNTYPED_TODAY so its row is checked"
        );
    }
}

#[test]
fn every_tool_response_type_deserialises_a_sample_of_its_handler_schema() {
    let schemas = schemas();
    let mut failures = Vec::new();
    for (route, mcp_type, check) in CHECKS {
        if UNTYPED_TODAY.contains(route) {
            continue;
        }
        let found = schemas
            .route(route)
            .unwrap_or_else(|| panic!("{route} is not a route"));
        let response = found["response"].as_str().unwrap_or_default();
        assert!(
            !UNTYPED_RESPONSES.contains(&response),
            "{route} answers `{response}`, which has no fields to sample; type the handler's \
             reply or list the route in UNTYPED_TODAY"
        );
        let value = sample(response, &schemas.types, 0);
        if let Err(e) = check(value.clone()) {
            failures.push(format!(
                "{route}: {mcp_type} does not read {response}: {e}\n  sample: {value}"
            ));
        }
    }
    assert!(failures.is_empty(), "\n{}", failures.join("\n"));
}
